const v=wb.getRange("Volume!A3:F68").getValues();
const hdr=wb.getRange("Volume!D2:F2").getValues()[0];
const c={};const un=[];let dirty=[];
rows.forEach((r,i)=>{const k=[r[1],r[3],r[4]].join('|');c[r[3]+'/'+r[4]]=(c[r[3]+'/'+r[4]]||0)+1;
 [r[1],r[3],r[4]].forEach(x=>{if(String(x)!==String(x).trim())dirty.push(i+2)});
 const m=v.filter(x=>x[0]===r[1]&&x[1]===r[4]);if(!m.length||!hdr.includes(r[3]))un.push(i+2+':'+k)});
const vd=v.flat().filter(x=>typeof x==='string'&&x!==x.trim()).length;
const keys={};rows.forEach((r,i)=>{const k=[r[1],r[3],r[4]].join('|');(keys[k]=keys[k]||[]).push(i+2)});
const dupes=Object.entries(keys).filter(([k,a])=>a.length>1);
({counts:c,unmatched:un,dirty,vd,dupes,hdrs:hdr})

